core;", "    // s_scores[token_idx] = score;", "    // s_positions[token_idx] = cached_position;", "  }", "  __syncthreads();", "", "  // Calculate the victim token index", "  __shared__ int left_victim_token_idx;", "  __shared__ int right_victim_token_idx;", "", "  if (context_len + 1 <= kv_buffer_size) {", "    if (thread_idx == 0) {", "      // The new token is appended to a high precision block", "      left_victim_token_idx = context_len_left;", "      kv_len_tables[kv_len_tables_offset] += 1;", "      right_victim_token_idx = -1;", "    }", "    __syncthreads();", "  } else {", "    // NOTE: we no more normalize token score over the entire sequence", "    // but just use its own mean score for refernece", "", "    // Step 1: Reduction across threads in the block", "    __shared__ float s_min_scores[NUM_THREADS_DECODE];", "    __shared__ int s_min_idxs[NUM_THREADS_DECODE];", "    s_min_scores[thread_idx] = local_min_score_left;", "    s_min_idxs[thread_idx] = local_min_idx_left;", "    __syncthreads();", "", "#pragma unroll", "    for (unsigned int s = NUM_THREADS_DECODE / 2; s > 0; s >>= 1) {", "      if (thread_idx < s) {", "        if (s_min_scores[thread_idx + s] < s_min_scores[thread_idx]) {", "          s_min_scores[thread_idx] = s_min_scores[thread_idx + s];", "          s_min_idxs[thread_idx] = s_min_idxs[thread_idx + s];", "        }", "      }", "      __syncthreads();", "    }", "", "    float min_score_left = s_min_scores[0];", "    int min_idx_left = s_min_idxs[0];", "", "    /* Sort tokens from low precision blocks */", "    // Step 1: Reduction across threads in the block", "    s_min_scores[thread_idx] = local_min_score_right;", "    s_min_idxs[thread_idx] = local_min_idx_right;", "    __syncthreads();", "", "#pragma unroll", "    for (unsigned int s = NUM_THREADS_DECODE / 2; s > 0; s >>= 1) {", "      if (thread_idx < s) {", "        if (s_min_scores[thread_idx + s] < s_min_scores[thread_idx]) {", "          s_min_scores[thread_idx] = s_min_scores[thread_idx + s];", "          s_min_idxs[thread_idx] = s_min_idxs[thread_idx + s];", "        }", "      }", "      __syncthreads();", "    }", "", "    float min_score_right = s_min_scores[0];", "    int min_idx_right = s_min_idxs[0];", "", "    // Compute actual threshold", "    // TODO: investigate using 1.0f / context_len (KV length) here", "    // const float base_threshold = 1.0f / context_len;", "    const float base_threshold = 1.0f / position;", "    const float prune_threshold = base_threshold * compress_config_tables[slot_idx * 2 + 0];", "    const float quant_threshold = base_threshold * compress_config_tables[slot_idx * 2 + 1];", "", "    assert(prune_threshold >= 0 && prune_threshold <= 1);", "    assert(quant_threshold >= 0 && quant_threshold <= 1);", "    assert(quant_threshold >= prune_threshold);", "", "    // Pruning and quantization policy", "    if (thread_idx == 0) {", "      if (min_score_left < prune_threshold && min_score_left < min_score_right) {", "        // Prune the left victim token", "        left_victim_token_idx = min_idx_left;", "        right_victim_token_idx = -1;", "      } else if (min_score_left < quant_threshold) {", "        if (min_score_right < prune_threshold) {", "          // Requantize the left victim token to low precision, occupying the space of the right victim token", "          left_victim_token_idx = min_idx_left;", "          right_victim_token_idx = min_idx_right;", "        } else {", "          // Requantize the left victim token to low precision, occupying a new slot", "          left_victim_token_idx = min_idx_left;", "          right_victim_token_idx = context_len_right + context_len_left;", "          kv_len_tables[kv_len_tables_offset + 1] += 1;", "        }", "      } else {", "        // Append the new token to a high precision block", "        left_victim_token_idx = context_len_left;", "        right_victim_token_idx = -1;", "        kv_len_tables[kv_len_tables_offset] += 1;", "      }", "    }",